INSERT INTO `chat_agent_version` (`created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`, `prompt_template`, `greeting_message`, `params`, `forest_option`)
VALUES
	('2025-10-10 14:24:14.123', '2025-10-10 14:24:14.123', NULL, @agent_id, '', '[1]', '0.5', 'prompt', 'For the queried data: {{input1}}\nMy question: {{input2}}\nThe chart type to generate: {{input3}} (bar: bar chart, pie: pie chart, line: line chart)\nBased on the above data and the user-specified chart type, generate the corresponding ECharts configuration.\n\nExample 1. Monthly Sales Bar Chart Analysis:\n{\n  \"title\": {\n    \"text\": \"Monthly Sales Performance Analysis\",\n    \"subtext\": \"Comparison of sales by month\",\n    \"left\": \"center\"\n  },\n  \"tooltip\": {\n    \"trigger\": \"axis\",\n    \"axisPointer\": {\n      \"type\": \"shadow\"\n    }\n  },\n  \"legend\": {\n    \"data\": [\"Sales\"],\n    \"left\": \"center\",\n    \"top\": \"8%\"\n  },\n  \"grid\": {\n    \"left\": \"3%\",\n    \"right\": \"4%\",\n    \"bottom\": \"15%\",\n    \"containLabel\": true\n  },\n  \"xAxis\": {\n    \"type\": \"category\",\n    \"data\": [\"January\", \"February\", \"March\", \"April\", \"May\", \"June\"]\n  },\n  \"yAxis\": {\n    \"type\": \"value\",\n    \"name\": \"Sales\"\n  },\n  \"series\": [\n    {\n      \"name\": \"Sales\",\n      \"type\": \"bar\",\n      \"data\": [120, 200, 150, 80, 70, 110],\n      \"itemStyle\": {\n        \"color\": \"#3b82f6\"\n      }\n    }\n  ]\n}\n\nExample 2. User Growth Trend Line Chart:\n{\n  \"title\": {\n    \"text\": \"User Growth Trend Analysis\",\n    \"subtext\": \"User growth over the past 6 months\",\n    \"left\": \"center\"\n  },\n  \"tooltip\": {\n    \"trigger\": \"axis\"\n  },\n  \"legend\": {\n    \"data\": [\"New Users\"],\n    \"left\": \"center\",\n    \"top\": \"8%\"\n  },\n  \"grid\": {\n    \"left\": \"3%\",\n    \"right\": \"4%\",\n    \"bottom\": \"15%\",\n    \"containLabel\": true\n  },\n  \"xAxis\": {\n    \"type\": \"category\",\n    \"data\": [\"Jan\", \"Feb\", \"Mar\", \"Apr\", \"May\", \"Jun\"]\n  },\n  \"yAxis\": {\n    \"type\": \"value\",\n    \"name\": \"Users\"\n  },\n  \"series\": [\n    {\n      \"name\": \"New Users\",\n      \"type\": \"line\",\n      \"data\": [850, 932, 901, 1234, 1290, 1430],\n      \"smooth\": true,\n      \"itemStyle\": {\n        \"color\": \"#10b981\"\n      },\n      \"lineStyle\": {\n        \"width\": 3\n      }\n    }\n  ]\n}\n\nExample 3. User Source Distribution Pie Chart:\n{\n	\"title\": {\n		\"text\": \"User Acquisition Channel Analysis\",\n		\"subtext\": \"Proportion of users by channel\",\n		\"left\": \"center\"\n	},\n	\"backgroundColor\": \"transparent\",\n	\"tooltip\": {\n		\"trigger\": \"item\",\n		\"formatter\": \"{a} <br/>{b}: {c} ({d}%)\"\n	},\n	\"legend\": {\n		\"orient\": \"vertical\",\n		\"left\": \"left\"\n	},\n	\"series\": [{\n		\"name\": \"User Source\",\n		\"type\": \"pie\",\n		\"radius\": \"50%\",\n		\"data\": [{\n				\"value\": 335,\n				\"name\": \"Search Engine\"\n			},\n			{\n				\"value\": 310,\n				\"name\": \"Direct Access\"\n			},\n			{\n				\"value\": 234,\n				\"name\": \"Email Marketing\"\n			},\n			{\n				\"value\": 135,\n				\"name\": \"Affiliate Ads\"\n			},\n			{\n				\"value\": 148,\n				\"name\": \"Video Ads\"\n			}\n		],\n		\"emphasis\": {\n			\"itemStyle\": {\n				\"shadowBlur\": 10,\n				\"shadowOffsetX\": 0,\n				\"shadowColor\": \"rgba(0, 0, 0, 0.5)\"\n			}\n		},\n		\"label\": {\n			\"show\": false\n		}\n	}]\n}\n\nExample 4. Product Rating Radar Analysis:\n{\n  \"title\": {\n    \"text\": \"Product Comprehensive Rating Analysis\",\n    \"subtext\": \"Comparison across six dimensions\",\n    \"left\": \"center\"\n  },\n  \"tooltip\": {\n    \"trigger\": \"item\"\n  },\n  \"legend\": {\n    \"data\": [\"Product A\", \"Product B\", \"Industry Average\"],\n    \"left\": \"center\",\n    \"bottom\": \"5%\"\n  },\n  \"radar\": {\n    \"indicator\": [\n      {\"name\": \"User Experience\", \"max\": 100},\n      {\"name\": \"Feature Completeness\", \"max\": 100},\n      {\"name\": \"Performance\", \"max\": 100},\n      {\"name\": \"Security\", \"max\": 100},\n      {\"name\": \"Usability\", \"max\": 100},\n      {\"name\": \"Cost Performance\", \"max\": 100}\n    ],\n    \"center\": [\"50%\", \"50%\"],\n    \"radius\": \"60%\"\n  },\n  \"series\": [\n    {\n      \"name\": \"Product Scores\",\n      \"type\": \"radar\",\n      \"data\": [\n        {\n          \"value\": [85, 90, 78, 92, 88, 85],\n          \"name\": \"Product A\",\n          \"itemStyle\": {\"color\": \"#3b82f6\"}\n        },\n        {\n          \"value\": [75, 85, 82, 88, 82, 90],\n          \"name\": \"Product B\", \n          \"itemStyle\": {\"color\": \"#ef4444\"}\n        },\n        {\n          \"value\": [70, 75, 75, 80, 75, 80],\n          \"name\": \"Industry Average\",\n          \"itemStyle\": {\"color\": \"#10b981\"}\n        }\n      ]\n    }\n  ]\n}\n\nExample 5. Website Traffic Heat Analysis:\n{\n  \"title\": {\n    \"text\": \"User Visit Time Distribution\",\n    \"subtext\": \"Scatter plot of visits over the week\",\n    \"left\": \"center\"\n  },\n  \"tooltip\": {\n    \"trigger\": \"item\",\n    \"formatter\": \"Time: {c[0]}h<br/>Visits: {c[1]}\"\n  },\n  \"grid\": {\n    \"left\": \"3%\",\n    \"right\": \"4%\",\n    \"bottom\": \"3%\",\n    \"containLabel\": true\n  },\n  \"xAxis\": {\n    \"type\": \"value\",\n    \"name\": \"Hour\",\n    \"min\": 0,\n    \"max\": 24\n  },\n  \"yAxis\": {\n    \"type\": \"value\",\n    \"name\": \"Visits\"\n  },\n  \"series\": [\n    {\n      \"name\": \"Visit Distribution\",\n      \"type\": \"scatter\",\n      \"symbolSize\": 15,\n      \"data\": [\n        [9, 1200], [10, 1500], [11, 1800], [12, 2100],\n        [13, 2000], [14, 2500], [15, 2800], [16, 2600],\n        [17, 2200], [18, 1900], [19, 2100], [20, 2400],\n        [21, 2000], [22, 1600], [23, 1200], [0, 800]\n      ],\n      \"itemStyle\": {\n        \"color\": \"#3b82f6\",\n        \"opacity\": 0.6\n      }\n    }\n  ]\n}\n\n\nRequirements:\n1. Numerical proportions and similar data must be explicitly shown.\n2. Only return the ECharts configuration; no extra content.\n3. The title.label should match the question’s language and summary.\n4. No fields in the ECharts configuration should contain functions.\n5. The chart type must match the user-specified type.\n6. If the generated chart is a pie chart, `label.show` must be set to false.', '', '[{\"input\":\"input1\",\"name\":\"Data\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true},{\"input\":\"input2\",\"name\":\"Question\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true},{\"input\":\"input3\",\"name\":\"Chart Type\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true}]', '{\"prompt_template\":\"\",\"doc_forest_ids\":null}');


