INSERT INTO `chat_agent_version` (`created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`, `prompt_template`, `greeting_message`, `params`, `forest_option`)
VALUES
	('2025-10-10 14:24:14.123', '2025-10-10 14:24:14.123', NULL, @agent_id, '', '[1]', '0.5', 'prompt', '對查詢出的數據：{{input1}}\n我的問題：{{input2}}\n需要生成的圖表類型：{{input3}}（bar：柱狀圖，pie：圓餅圖，line：折線圖）\n根據上述數據與使用者指定的圖表類型生成對應的 Echarts 圖表配置。\n範例 1 月度銷售柱狀圖分析：\n{\n  \"title\": {\n    \"text\": \"月度銷售業績分析\",\n    \"subtext\": \"各月份銷量對比\",\n    \"left\": \"center\"\n  },\n  \"tooltip\": {\n    \"trigger\": \"axis\",\n    \"axisPointer\": {\n      \"type\": \"shadow\"\n    }\n  },\n  \"legend\": {\n    \"data\": [\"銷量\"],\n    \"left\": \"center\",\n    \"top\": \"8%\"\n  },\n  \"grid\": {\n    \"left\": \"3%\",\n    \"right\": \"4%\",\n    \"bottom\": \"15%\",\n    \"containLabel\": true\n  },\n  \"xAxis\": {\n    \"type\": \"category\",\n    \"data\": [\"一月\", \"二月\", \"三月\", \"四月\", \"五月\", \"六月\"]\n  },\n  \"yAxis\": {\n    \"type\": \"value\",\n    \"name\": \"銷量\"\n  },\n  \"series\": [\n    {\n      \"name\": \"銷量\",\n      \"type\": \"bar\",\n      \"data\": [120, 200, 150, 80, 70, 110],\n      \"itemStyle\": {\n        \"color\": \"#3b82f6\"\n      }\n    }\n  ]\n}\n\n範例 2 使用者增長趨勢折線圖：\n{\n  \"title\": {\n    \"text\": \"使用者增長趨勢分析\",\n    \"subtext\": \"近6個月使用者增長情況\",\n    \"left\": \"center\"\n  },\n  \"tooltip\": {\n    \"trigger\": \"axis\"\n  },\n  \"legend\": {\n    \"data\": [\"新增使用者\"],\n    \"left\": \"center\",\n    \"top\": \"8%\"\n  },\n  \"grid\": {\n    \"left\": \"3%\",\n    \"right\": \"4%\",\n    \"bottom\": \"15%\",\n    \"containLabel\": true\n  },\n  \"xAxis\": {\n    \"type\": \"category\",\n    \"data\": [\"1月\", \"2月\", \"3月\", \"4月\", \"5月\", \"6月\"]\n  },\n  \"yAxis\": {\n    \"type\": \"value\",\n    \"name\": \"使用者數\"\n  },\n  \"series\": [\n    {\n      \"name\": \"新增使用者\",\n      \"type\": \"line\",\n      \"data\": [850, 932, 901, 1234, 1290, 1430],\n      \"smooth\": true,\n      \"itemStyle\": {\n        \"color\": \"#10b981\"\n      },\n      \"lineStyle\": {\n        \"width\": 3\n      }\n    }\n  ]\n}\n\n範例 3 使用者來源分佈圓餅圖：\n{\n	\"title\": {\n		\"text\": \"使用者獲取渠道分析\",\n		\"subtext\": \"各渠道使用者占比\",\n		\"left\": \"center\"\n	},\n	\"backgroundColor\": \"transparent\",\n	\"tooltip\": {\n		\"trigger\": \"item\",\n		\"formatter\": \"{a} <br/>{b}: {c} ({d}%)\"\n	},\n	\"legend\": {\n		\"orient\": \"vertical\",\n		\"left\": \"left\"\n	},\n	\"series\": [{\n		\"name\": \"使用者來源\",\n		\"type\": \"pie\",\n		\"radius\": \"50%\",\n		\"data\": [{\n				\"value\": 335,\n				\"name\": \"搜尋引擎\"\n			},\n			{\n				\"value\": 310,\n				\"name\": \"直接訪問\"\n			},\n			{\n				\"value\": 234,\n				\"name\": \"郵件行銷\"\n			},\n			{\n				\"value\": 135,\n				\"name\": \"聯盟廣告\"\n			},\n			{\n				\"value\": 148,\n				\"name\": \"影片廣告\"\n			}\n		],\n		\"emphasis\": {\n			\"itemStyle\": {\n				\"shadowBlur\": 10,\n				\"shadowOffsetX\": 0,\n				\"shadowColor\": \"rgba(0, 0, 0, 0.5)\"\n			}\n		},\n		\"label\": {\n			\"show\": false\n		}\n	}]\n}\n\n範例 4 產品評分雷達分析：\n{\n  \"title\": {\n    \"text\": \"產品綜合評分分析\",\n    \"subtext\": \"六個維度評估對比\",\n    \"left\": \"center\"\n  },\n  \"tooltip\": {\n    \"trigger\": \"item\"\n  },\n  \"legend\": {\n    \"data\": [\"產品A\", \"產品B\", \"行業平均\"],\n    \"left\": \"center\",\n    \"bottom\": \"5%\"\n  },\n  \"radar\": {\n    \"indicator\": [\n      {\"name\": \"使用者體驗\", \"max\": 100},\n      {\"name\": \"功能完整度\", \"max\": 100},\n      {\"name\": \"效能表現\", \"max\": 100},\n      {\"name\": \"安全性\", \"max\": 100},\n      {\"name\": \"易用性\", \"max\": 100},\n      {\"name\": \"性價比\", \"max\": 100}\n    ],\n    \"center\": [\"50%\", \"50%\"],\n    \"radius\": \"60%\"\n  },\n  \"series\": [\n    {\n      \"name\": \"產品評分\",\n      \"type\": \"radar\",\n      \"data\": [\n        {\n          \"value\": [85, 90, 78, 92, 88, 85],\n          \"name\": \"產品A\",\n          \"itemStyle\": {\"color\": \"#3b82f6\"}\n        },\n        {\n          \"value\": [75, 85, 82, 88, 82, 90],\n          \"name\": \"產品B\", \n          \"itemStyle\": {\"color\": \"#ef4444\"}\n        },\n        {\n          \"value\": [70, 75, 75, 80, 75, 80],\n          \"name\": \"行業平均\",\n          \"itemStyle\": {\"color\": \"#10b981\"}\n        }\n      ]\n    }\n  ]\n}\n\n範例 5 網站流量熱力分析：\n{\n  \"title\": {\n    \"text\": \"使用者訪問時間分佈\",\n    \"subtext\": \"一週內各時段訪問量散點分析\",\n    \"left\": \"center\"\n  },\n  \"tooltip\": {\n    \"trigger\": \"item\",\n    \"formatter\": \"時間: {c[0]}點<br/>訪問量: {c[1]}\"\n  },\n  \"grid\": {\n    \"left\": \"3%\",\n    \"right\": \"4%\",\n    \"bottom\": \"3%\",\n    \"containLabel\": true\n  },\n  \"xAxis\": {\n    \"type\": \"value\",\n    \"name\": \"小時\",\n    \"min\": 0,\n    \"max\": 24\n  },\n  \"yAxis\": {\n    \"type\": \"value\",\n    \"name\": \"訪問量\"\n  },\n  \"series\": [\n    {\n      \"name\": \"訪問分佈\",\n      \"type\": \"scatter\",\n      \"symbolSize\": 15,\n      \"data\": [\n        [9, 1200], [10, 1500], [11, 1800], [12, 2100],\n        [13, 2000], [14, 2500], [15, 2800], [16, 2600],\n        [17, 2200], [18, 1900], [19, 2100], [20, 2400],\n        [21, 2000], [22, 1600], [23, 1200], [0, 800]\n      ],\n      \"itemStyle\": {\n        \"color\": \"#3b82f6\",\n        \"opacity\": 0.6\n      }\n    }\n  ]\n}\n\n\n要求：\n1、數值比例等內容需要明確展示\n2、僅返回 Echarts 的圖表配置，無需其他多餘內容。\n3、title.label 根據問題摘要，語言與問題一致\n4、Echarts 的所有字段中都不要出現 function！！！\n5、必須根據使用者要求的圖表類型生成對應的圖表！！！\n6、如果生成的圖表是圓餅圖（pie），配置中的 label.show 必須為 false', '', '[{\"input\":\"input1\",\"name\":\"數據\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true},{\"input\":\"input2\",\"name\":\"問題\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true},{\"input\":\"input3\",\"name\":\"圖表類型\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true}]', '{\"prompt_template\":\"\",\"doc_forest_ids\":null}');

